/* zxv_shell_apps.c — the app catalogue and its 407 vector icons, linked into
 * the kernel image.
 *
 * assets/icons/apps/zxv-apps.zxap is generated by tools/zui/gen_appicons.py
 * from the catalogue and the icon vectors, and read by zui_apps (AP1..AP4).
 * It is placed in the image as it is, with .incbin (the build runs from the
 * repository root), in its own section so --gc-sections drops it from an
 * image that never draws the desktop. */
#include "zxv_shell.h"

__asm__(".pushsection .rodata.zxv_shell_apps,\"a\"\n"
        ".balign 4\n"
        ".global zxv_shell_apps_start\n"
        "zxv_shell_apps_start:\n"
        ".incbin \"assets/icons/apps/zxv-apps.zxap\"\n"
        ".global zxv_shell_apps_end\n"
        "zxv_shell_apps_end:\n"
        ".popsection\n");

extern const uint8_t zxv_shell_apps_start[];
extern const uint8_t zxv_shell_apps_end[];

const uint8_t *zxv_shell_apps_data(void)
{
    return zxv_shell_apps_start;
}

uint32_t zxv_shell_apps_size(void)
{
    return (uint32_t) (zxv_shell_apps_end - zxv_shell_apps_start);
}
